CREATE TABLE "ValidationPolicy" ("id" TEXT NOT NULL, "requiredServices" INTEGER NOT NULL DEFAULT 3, "isActive" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ValidationPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ValidationServiceRecord" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "externalServiceId" TEXT NOT NULL, "wasOnTime" BOOLEAN, "rating" INTEGER, "hadIssue" BOOLEAN, "wouldHireAgain" "WouldHireAgain", "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ValidationServiceRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ValidationDecision" ("id" TEXT NOT NULL, "leadId" TEXT NOT NULL, "decision" "RecruitmentStatus" NOT NULL, "eligible" BOOLEAN NOT NULL, "reason" TEXT, "decidedBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ValidationDecision_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ValidationServiceRecord_externalServiceId_key" ON "ValidationServiceRecord"("externalServiceId"); CREATE INDEX "ValidationServiceRecord_leadId_idx" ON "ValidationServiceRecord"("leadId"); CREATE INDEX "ValidationDecision_leadId_idx" ON "ValidationDecision"("leadId");
ALTER TABLE "ValidationServiceRecord" ADD CONSTRAINT "ValidationServiceRecord_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "RecruitmentLead"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ValidationDecision" ADD CONSTRAINT "ValidationDecision_leadId_fkey" FOREIGN KEY ("leadId") REFERENCES "RecruitmentLead"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
